// Vacant (vacant-intake) — generated by `vacant install`; remove with `vacant uninstall`.
// Forwards pi events to `vacant hook pi <event>` and applies the decision it prints.
import { spawn } from "node:child_process";

const ARGV = ["/home/user/Vacant/.venv/bin/python", "-m", "vacant_network", "hook", "pi"];
const TIMEOUT = { prompt: 30000, pre_tool: 30000, post_tool: 30000, stop: 600000, session_end: 30000,
                  turn_check: 20000 };

// Zero-config v3: a turn budget the agent was told about (e.g. "a hard budget of 15 model turns" in its
// system prompt). Only the system prompt counts: a budget nobody enforces is not read from the person's
// words. The LAST such sentence wins: a harness appends its cap after the project's own instructions
// (AGENTS.md and the like, which pi also puts into the system prompt). TURNS counts every model turn in
// this process, the same way a turn cap counts them — except the synthetic turn pi runs right after an
// abort (it sends nothing to the model). ABORTED: this request was cut off (a cap, or the person's Esc).
// LAST_FINAL: the last model turn was a final answer (no tool calls). A cap that aborts in its own
// turn_end handler stops pi before agent_before_settle even then, so the agent said it was done and
// the delivery check never ran; the session end runs it afterwards, for the person only (v3.2).
const BUDGET_RE = /\b(?:budget|limit|maximum|max|at most|no more than|up to)\b[^.\n]{0,40}?\b(\d{1,4})\s+(?:model\s+|agent\s+|llm\s+)?turns\b/i;
let BUDGET = null;
let TURNS = 0;
let ABORTED = false;
let LAST_FINAL = false;
let LAST_TEXT = "";
let LAST_STOP = null;   // how the last real turn ended (pi's stopReason): "error" ⇒ the check runs after a model error

function readBudget(text) {
  try {
    let n = NaN;
    for (const m of String(text || "").matchAll(new RegExp(BUDGET_RE.source, "gi"))) n = Number(m[1]);
    return Number.isFinite(n) && n >= 4 ? n : null;
  } catch (e) { return null; }
}

// Asynchronous on purpose: a stop check can take minutes, and spawnSync would freeze
// pi's TUI and streaming for that long. Every handler below is awaited by pi.
function ask(event, payload, ms) {
  return new Promise((resolve) => {
    let out = "";
    let done = false;
    const finish = (v) => { if (!done) { done = true; resolve(v); } };
    try {
      const child = spawn(ARGV[0], [...ARGV.slice(1), event], { stdio: ["pipe", "pipe", "ignore"] });
      const timer = setTimeout(() => { try { child.kill("SIGKILL"); } catch (e) {} finish({ action: "allow" }); },
                               ms || TIMEOUT[event] || 30000);
      child.stdout.on("data", (b) => { out += b; });
      child.on("error", () => { clearTimeout(timer); finish({ action: "allow" }); });
      child.on("close", () => {
        clearTimeout(timer);
        try {
          const line = out.trim().split("\n").pop() || "";
          finish(line ? JSON.parse(line) : { action: "allow" });
        } catch (e) { finish({ action: "allow" }); }   // a broken hook must not kill the agent
      });
      child.stdin.end(JSON.stringify(payload || {}));
    } catch (e) {
      finish({ action: "allow" });
    }
  });
}

function sid(ctx) {
  try { return ctx.sessionManager.getSessionId(); } catch (e) { return undefined; }
}

function mid(ctx) {   // the model pi says it is using (a claim, not an observation)
  try { return ctx.model ? `${ctx.model.provider}/${ctx.model.id}` : undefined; } catch (e) { return undefined; }
}

// The agent's last message of this turn (Vacant checks claims such as "tests pass" against the record).
function finalText(event) {
  try {
    const ms = (event && event.context && event.context.llmMessages) || [];
    for (let i = ms.length - 1; i >= 0; i--) {
      const m = ms[i];
      if (!m || m.role !== "assistant") continue;
      const t = typeof m.content === "string" ? m.content : text(m.content);
      if (t && t.trim()) return t.slice(0, 20000);
    }
  } catch (e) {}
  return undefined;
}

function text(content) {
  try { return (content || []).filter((c) => c && c.type === "text").map((c) => c.text).join("\n"); }
  catch (e) { return undefined; }
}

// pi has no built-in sub-agents: extensions (like the shipped `subagent` example) start another
// pi process. This process leaves one fixed mark in its environment (its root session, its pid,
// its project); a pi started from it accepts the mark only if that pid is still alive, is one of
// its own ancestors, and works in the same project. Then it reports itself as a sub-agent of that
// session: its turn end is not the task's end and its exit does not end the session. Which call
// started it is worked out by Vacant from the task text, not from the mark.
import { readFileSync } from "node:fs";
import { execFileSync } from "node:child_process";
import * as nodePath from "node:path";

const MARK = "VACANT_PI_PARENT";
const SELF = "VACANT_PI_SELF";

function parentOf(pid) {
  try {   // Linux
    const m = /\nPPid:\s*(\d+)/.exec(readFileSync(`/proc/${pid}/status`, "utf8"));
    if (m) return Number(m[1]);
  } catch (e) {}
  try {   // macOS and others
    return Number(execFileSync("ps", ["-o", "ppid=", "-p", String(pid)], { encoding: "utf8" }).trim());
  } catch (e) { return 0; }
}

function isAncestor(pid) {
  let p = process.ppid;
  for (let i = 0; i < 64 && p > 1; i++) {
    if (p === pid) return true;
    p = parentOf(p);
  }
  return false;
}

function inside(child, parent) {
  const c = nodePath.resolve(child), p = nodePath.resolve(parent);
  return c === p || c.startsWith(p + nodePath.sep);
}

function loadParent() {
  try {   // an extension reload in this same process keeps what it was
    const s = JSON.parse(process.env[SELF] || "null");
    if (s && s.pid === process.pid) return s.parent || null;
  } catch (e) {}
  let m = null;
  try { m = JSON.parse(process.env[MARK] || "null"); } catch (e) { m = null; }
  const ok = m && typeof m.pid === "number" && m.pid !== process.pid && m.session &&
             isAncestor(m.pid) && m.cwd && inside(process.cwd(), m.cwd);
  const parent = ok ? { session: m.session, parent_agent: m.agent } : null;
  process.env[SELF] = JSON.stringify({ pid: process.pid, parent });
  return parent;
}

const PARENT = loadParent();

function mark(ctx) {   // what a pi started from this process will read
  const me = sid(ctx);
  if (!me) return;
  process.env[MARK] = JSON.stringify({
    session: PARENT ? PARENT.session : me, pid: process.pid, cwd: process.cwd(),
    agent: PARENT ? me : undefined });
}

function who(ctx) {
  const base = { cwd: ctx.cwd, session_id: sid(ctx) };
  if (!PARENT || PARENT.session === base.session_id) return base;
  return { ...base, parent_session_id: PARENT.session, parent_agent_id: PARENT.parent_agent };
}

export default function (pi) {
  // Accountable trace: the task message (is a wrong value in the answer something the task gave?).
  pi.on("before_agent_start", async (event, ctx) => {
    mark(ctx);
    ABORTED = false;
    LAST_FINAL = false;
    LAST_TEXT = "";
    LAST_STOP = null;
    if (BUDGET === null) BUDGET = readBudget(event && event.systemPrompt);
    await ask("prompt", { ...who(ctx), prompt: event && event.prompt });
    return undefined;
  });
  // A request typed while the agent is still running (queued as a steer / follow-up) never reaches
  // before_agent_start; record it too, so it is the person's and starts a fresh feedback budget.
  // Idle input is left to before_agent_start (recording it here too would count it twice).
  pi.on("input", async (event, ctx) => {
    if (!event || !event.streamingBehavior || event.source === "extension") return undefined;
    await ask("prompt", { ...who(ctx), prompt: event.text || "" });
    return undefined;
  });
  pi.on("tool_call", async (event, ctx) => {
    mark(ctx);
    const d = await ask("pre_tool", { ...who(ctx), tool: event.toolName, input: event.input || {},
                                      call_id: event.toolCallId, model: mid(ctx) });
    if (d.action === "deny") return { block: true, reason: d.reason };
    return undefined;
  });
  // Accountable trace: what each step returned (the step's writes are Vacant's own diff).
  pi.on("tool_result", async (event, ctx) => {
    await ask("post_tool", { ...who(ctx), tool: event.toolName, input: event.input || {},
                             call_id: event.toolCallId, output: text(event.content),
                             is_error: !!event.isError, model: mid(ctx) });
    return undefined;
  });
  // Zero-config v3: near the end of a stated turn budget, if a file the request asks for does not exist
  // yet, one short reminder rides the request that goes out next anyway (no extra model request; never on
  // the capped turn itself, which is already aborted). Without a stated budget nothing is sent here.
  pi.on("turn_end", async (event, ctx) => {
    const synthetic = ABORTED && event && event.message && event.message.stopReason === "error";
    if (!synthetic) {
      TURNS += 1;
      const m = (event && event.message) || {};
      LAST_STOP = m.stopReason || null;
      LAST_FINAL = !((event && event.toolResults) || []).length && m.stopReason === "stop";
      LAST_TEXT = LAST_FINAL ? String((typeof m.content === "string" ? m.content : text(m.content)) || "")
                               .slice(0, 20000) : "";
    }
    if (ctx.signal && ctx.signal.aborted) ABORTED = true;
    try {
      if (BUDGET === null && ctx.getSystemPrompt) BUDGET = readBudget(ctx.getSystemPrompt());
    } catch (e) {}
    if (BUDGET === null || who(ctx).parent_session_id) return undefined;
    const left = BUDGET - TURNS;
    if (left < 1 || left > 2) return undefined;
    if (ctx.signal && ctx.signal.aborted) return undefined;
    if (!event || !(event.toolResults || []).length) return undefined;   // a final answer goes to the stop check
    const d = await ask("turn_check", { ...who(ctx), turn: TURNS, budget: BUDGET });
    if (d.action === "continue" && d.reason) {
      return { entries: [...((event && event.entries) || []),
                         { type: "custom_message", customType: "vacant-budget", content: d.reason, display: true }] };
    }
    return undefined;
  });
  pi.on("agent_before_settle", async (event, ctx) => {
    if (who(ctx).parent_session_id) return undefined;   // a sub-agent's turn end is not the task's end
    const d = await ask("stop", { ...who(ctx), final_text: finalText(event), turn: TURNS, budget: BUDGET,
                                  last_stop: LAST_STOP || undefined });
    if (d.action === "continue" && d.reason) {
      return { entries: [...((event && event.entries) || []),
                         { type: "custom_message", customType: "vacant-check", content: d.reason, display: true }],
               continue: true };
    }
    // The delivery note is for the person, never for the model; print mode (-p) has no UI and
    // gets nothing on screen (scripts read pi's output), the note stays in Vacant's data folder.
    try { if (d.note && ctx.hasUI && ctx.ui) ctx.ui.notify(d.note, "info"); } catch (e) {}
    return undefined;
  });
  pi.on("session_shutdown", async (event, ctx) => {
    // reason: quit | reload | new | resume | fork — only `quit` ends the work
    const w = who(ctx);
    // said done, then stopped (a cap's abort, or exactly the stated budget used up) before the check
    // could run. Over the stated budget means nobody enforces it (v3.1), so only TURNS === BUDGET counts.
    const late = !w.parent_session_id && LAST_FINAL && (ABORTED || (BUDGET !== null && TURNS === BUDGET));
    // the check after the end (v3.2/v3.3) gets the same time limit as the Stop check, not session_end's 30 s
    await ask(w.parent_session_id ? "subagent_stop" : "session_end",
              { ...w, reason: (event && event.reason) || undefined, turn: TURNS, budget: BUDGET,
                aborted: ABORTED, final_answer: LAST_FINAL,
                final_text: late ? LAST_TEXT || undefined : undefined },
              !w.parent_session_id && (late || ABORTED) ? TIMEOUT.stop : undefined);
  });
}
